import os
import re
from taf.ul.sc.util import util
from taf.ul.sc.uesim.generic_workstation import GenericWorkstation
from taf.ul.sc.uesim.cus.cus_build import CusBuild
from taf.ul.sc.uesim.rtg_config_converter import RtgConfigConverter
from moler.device import DeviceFactory


class Workstation(GenericWorkstation):

    def __init__(self,
                 device_name='CUS_WS',                              # type: 'Optional[str]'
                 device=None,                                       # type: 'Optional[CUS]'
                 autoconnect=True,                                 # type: 'Optional[bool]'
                 scenarios_dir='/home/cus/test/scenarios/',         # type: 'Optional[str]'
                 logs_dir='/home/cus/logs/',                        # type: 'Optional[str]'
                 config_dir='/opt/cus/etc',                         # type: 'Optional[str]'
                 config_file='cus.ini',                             # type: 'Optional[str]'
                 dhcp_configuration_file='/etc/dhcp/dhcpd.conf',    # type: 'Optional[str]'
                 ue_cap_dir='/home/cus/test/ue_capabilities/',      # type: 'Optional[str]'
                 get_device=False                                   # type: 'Optional[bool]'
                 ):
        """
        :param device_name: Moler device name - by default CUS_WS.
        :param device Moler CUS device. Initial state should be set to WS
        :param autoconnect: Connect to device after create object.
        :param scenarios_dir: Path to directory with test scenarios.
        :param logs_dir: Base path to directory with execution logs.
        :param config_dir: Path to directory with cus configuration.
        :param config_file: Ini config file name.
        :param ue_cap_dir: Path to directory with cus UE CAP configuration.
        :param dhcp_configuration_file: path to dhcpd.conf file.
        """
        super(Workstation, self).__init__(device_name=device_name, device=device, autoconnect=autoconnect,
                                          scenarios_dir=scenarios_dir, logs_dir=logs_dir, config_dir=config_dir,
                                          config_file=config_file, dhcp_configuration_file=dhcp_configuration_file,
                                          ue_cap_dir=ue_cap_dir, get_device=get_device)
        self._cus_version = None

    def collect_cus_configuration_file(self, execution_dir, destination_dir):
        """
        SCP cus.ini file from CUS workstation to UnixLocal.
        :param execution_dir: Subpath to logs execution dir. eg: attach_auto/20190807-163723/
        :param destination_dir: Target directory where cus.ini will be downloaded
        :return: None
        """
        util().download_files(local_dir=destination_dir,
                              remote_file=self.config_file,
                              remote_dir=os.path.join(self.logs_dir, execution_dir),
                              remote_device_name=self.name
                              )

    def change_configuration_file(self, config_file, config_dir='/opt/cus/etc'):
        """
        Change configuration file on CUS workstation.

        :param config_file: Configuration file name.
        :param config_dir: Configuration file directory.
        :return: None
        """
        self.config_file = config_file
        self.config_dir = config_dir

    def restart_trace(self):
        """
        Method for restarting cus-trace process.

        :return: None
        """
        self.device.goto_state(self.root_state)
        restart_trace_cmd_params = {"script_command": '/etc/init.d/cus-trace restart'}
        restart_trace_cmd = self.device.get_cmd(cmd_name="run_script", cmd_params=restart_trace_cmd_params)
        # run command
        restart_trace_cmd(timeout=60)
        self.device.goto_state(self.basic_state)

    def restart_executor(self):
        """
        Function for restarting cus-executor process.

        :return:
        """
        self.device.goto_state(self.root_state)
        restart_executor_cmd_params = {"script_command": '/etc/init.d/cus-executor restart'}
        restart_executor_cmd = self.device.get_cmd(cmd_name="run_script", cmd_params=restart_executor_cmd_params)
        restart_executor_cmd(timeout=60)
        self.device.goto_state(self.basic_state)

    def update_cus(self, update_file=None, options=None, timeout=1800):
        """Run cus-update script.

        :param update_file: RPM/DEB file witch with script will be run if None script will be run with -nofile option
        :param options: Options for cus-update script
        :return:
        """
        self.device.goto_state(self.root_state)
        cus_update = self.device.get_cmd(cmd_name="cus_update",
                                         cmd_params={"update_file": update_file, "options": options})
        cus_update(timeout=timeout)
        self.device.goto_state(self.basic_state)

    def get_cus_build(self, proxy=None):
        cus_build = CusBuild(self.device, proxy)
        cus_build.download_cus_build()
        return cus_build.local_build_path

    def start_wireshark(self, ctrls=None, options=None, timeout=240):
        """Star collecting wireshark logs.

        :param ctrls: List with controllers. Example: [1, 2]
        :param options: Options for rtg pcap command
        :return: None
        """
        cus_version = self._get_cus_version()
        if cus_version == '1' and ctrls is None:
            raise TypeError("start_wireshark() missing 1 required argument: 'ctrls'")
        cmd_name = {'1': 'cus_pcap_start', '2': 'cus2_pcap_start', '3': 'cus_pcap_start'}[cus_version]
        if options:
            self.setup_type = 'NB' if '--nb' in options else 'LTE'
        else:
            self._get_setup_type(ctrls[0])
            if self.setup_type == 'NB':
                options = '--nb --sch --phy --payload 2'
            else:
                options = '--sch --phy --payload 2'
        cmd_params = {'options': options}
        if ctrls and cus_version != '2':
            cmd_params.update({'ctrls': ctrls})

        self.device.goto_state(self.root_state)
        self.device_wireshark = DeviceFactory.get_cloned_device(self.device, "CUS_WIRESHARK")
        cmd_start = self.device_wireshark.get_cmd(cmd_name=cmd_name, cmd_params=cmd_params)
        cmd_start(timeout=timeout)

    def _get_setup_type(self, ctrl):
        config = self.get_file_content(os.path.join(self.config_dir, self.config_file))
        config = RtgConfigConverter('\n'.join(config)).get_config_dict()
        sectors = config['ctrl'][str(ctrl)]['sectors'].split(',')
        self.setup_type = 'LTE'
        try:
            for nb_cell in config.get('nb_cell').values():
                valid_parents = list(sectors) + ['{}.{}'.format(sector, ctrl) for sector in sectors]
                if str(nb_cell['parent_sector']) in valid_parents:
                    self.setup_type = 'NB'
                    break
        finally:
            return self.setup_type

    def _get_cus_version(self):
        if self._cus_version is None:
            self.device.goto_state('CUS')
            build = self.device.get_cmd(cmd_name='version')()['BUILD']
            match = re.search(r'(?:CUS_(?P<cus_version>1|2)\.\d\.[A-Z0-9]+\.\d{6}\.\d)|(CUS\.\d+\.\d+)', build)
            if match.group('cus_version') is None:
                self._cus_version = '3'
            else:
                self._cus_version = match.group('cus_version')
        return self._cus_version

    def stop_wireshark(self, timeout=240):
        """Stop collecting wireshark logs.

        :return: Rtg pcap stop command result.
        :param timeout: Timeout for executing command.
        """
        if self.device_wireshark:
            cmd_name = {'1': 'cus_pcap_stop', '2': 'cus2_pcap_stop', '3': 'cus_pcap_stop',}[self._get_cus_version()]
            cmd_stop = self.device_wireshark.get_cmd(cmd_name=cmd_name)
            result = cmd_stop(timeout=timeout)
            self.device.goto_state(self.basic_state)
            self._pcap_dir = result['OUTPUT_LOG_DIR']
            self._pcap_file = result['OUTPUT_LOG_FILE']
            return result

    def get_pcap_file_path(self):
        if hasattr(self, '_pcap_file'):
            return self._pcap_file
        else:
            raise RuntimeError('No pcap file collected')

    def set_python_source(self, path='/home/ute/test_repo/bin/activate'):
        """
        Run script which sets virtual environment for python. This is needed for devices using python scripts.

        :param path: Path where source activation script is stored
        """
        cmd_set_python_source = self.device.get_cmd(cmd_name="run_script",
                                                    cmd_params={'script_command': 'source {}'.format(path)})
        cmd_set_python_source(timeout=30)

    def generate_tti_trace(self, pcap_dir=None, output_dir=None, options=None, timeout=900, set_venv=False):
        """
        Run script which generate tti trace files from pcap package.

        :param pcap_dir: Path to directory with pcaps.
        :param output_dir: Path to target directory for tti trace.
        :param options: Generate tti trace command options .
        :param timeout: Generate tti trace command timeout.
        :param set_venv: Set source for python scripts
        :return: None
        """
        pcap_dir = pcap_dir if pcap_dir else self._pcap_dir
        output_dir = output_dir if output_dir else os.path.join(self.logs_dir, 'ttitrace')
        if set_venv:
            self.set_python_source()
        if options is None:
            options = '--nb 0' if self.setup_type == 'LTE' else '--nb 1'
        cmd_generate_tti_trace = self.device.get_cmd(cmd_name="generate_tti_trace", cmd_params={'src': pcap_dir,
                                                                                                'dst': output_dir,
                                                                                                'options': options})
        cmd_generate_tti_trace(timeout=timeout)

    def collect_tti_trace(self, destination_dir, source_dir=None, timeout=180):
        """
        SCP tti trace files from CUS workstation to UnixLocal.

        :param destination_dir: Target directory where tti trace files will be downloaded.
        :param source_dir: Source dir with tti traces.
        :param timeout: SCP command timeout.
        :return: None
        """
        source_dir = source_dir if source_dir else os.path.join(self.logs_dir, 'ttitrace')
        util().download_files(local_dir=os.path.join(destination_dir, 'ttitrace'),
                              remote_file="*",
                              remote_dir=source_dir,
                              remote_device_name=self.name,
                              timeout=timeout
                              )

    def get_not_connected_controllers(self, timeout=20):
        """
        Get list with controllers which do not have connection with workstation.

        :param timeout: Command cus-util timeout.
        :return: List with not connected controllers. Example: ['CTRL-01', 'CTRL-02']
        """
        check_cmd = self.device.get_cmd(cmd_name='cus_util', cmd_params={'usage': 'check'})
        result = check_cmd(timeout)
        not_connected_controllers = []
        for ctrl in result:
            if result[ctrl]['CONNECTION_STATUS'] != 'OK':
                not_connected_controllers.append(ctrl)
        return not_connected_controllers
